import Foundation

@MainActor
class StatusPresenter {
    var status: String = "Offline"
    func updateStatus(to newStatus: String) {
        status = newStatus
        print("Status: \(status) on main: \(Thread.isMainThread)")
    }
}

let presenter = StatusPresenter()
presenter.updateStatus(to: "Online")
print("Final status: \(presenter.status)")

import Foundation

@MainActor
class UIViewModel {
    var title: String
    init(title: String) {
        self.title = title
    }
    func refresh(newTitle: String) {
        assert(Thread.isMainThread)
        self.title = newTitle
        print("Refreshed \(newTitle)")
    }
}

let vm = UIViewModel(title: "Home")
vm.refresh(newTitle: "Profile")
print("Done")

import Foundation

struct ScreenState {
    var count: Int
}

@MainActor
class NavigationCoordinator {
    var state = ScreenState(count: 0)
    func pushScreen() {
        state.count += 1
        print("Screens count: \(state.count)")
    }
}

let coordinator = NavigationCoordinator()
coordinator.pushScreen()
coordinator.pushScreen()
print("Finished navigation")
